const objectDoneTime=value=>{const parsed=Date.parse(String(value||''));return Number.isFinite(parsed)?parsed:null;};
const objectDoneCompletionAt=value=>objectDoneTime(value?.at);
const objectDoneReopenAt=value=>value?.value===null&&value?.reopen===true?objectDoneTime(value.reopenedAt):null;
function objectDoneState(value){const completed=objectDoneCompletionAt(value),reopened=objectDoneReopenAt(value);if(reopened!==null&&(completed===null||reopened>completed))return 'reopened';if(completed!==null)return 'completed';return 'absent';}
function normalizeObjectDoneWrite(value){
 if(!value||typeof value!=='object')return value;
 const completed=objectDoneCompletionAt(value),reopened=objectDoneReopenAt(value);
 if(completed!==null&&reopened===completed){const result=structuredClone(value);result.reopenedAt=new Date(completed+1).toISOString();return result;}
 return value;
}
function cleanObjectDone(value,actor,stampActor=false){const result=structuredClone(value);if(objectDoneState(result)==='reopened'){result.value=null;result.reopen=true;if(stampActor)result.reopenedBy=actor;}else{delete result.value;delete result.reopen;delete result.reopenedAt;delete result.reopenedBy;}return result;}
function resolveObjectDoneWrite(previous,incoming,actor){
 incoming=normalizeObjectDoneWrite(incoming);
 const before=objectDoneState(previous),next=objectDoneState(incoming);
 if(next==='absent')return before==='absent'?null:cleanObjectDone(previous,actor);
 if(before==='completed'&&next==='reopened'&&objectDoneReopenAt(incoming)<=objectDoneCompletionAt(previous))return cleanObjectDone(previous,actor);
 if(before==='reopened'&&next==='completed'&&objectDoneCompletionAt(incoming)<=objectDoneReopenAt(previous))return cleanObjectDone(previous,actor);
 if(before==='completed'&&next==='completed'&&objectDoneCompletionAt(incoming)<=objectDoneCompletionAt(previous))return cleanObjectDone(previous,actor);
 if(before==='reopened'&&next==='reopened'&&objectDoneReopenAt(incoming)<=objectDoneReopenAt(previous))return cleanObjectDone(previous,actor);
 return cleanObjectDone(incoming,actor,next==='reopened');
}
function resolveOfficeReportWrite(previous,incoming,user,role,now=new Date().toISOString()){
 const result=structuredClone(incoming||{}),before=previous&&typeof previous==='object'?previous:{};
 if(result.recalledAt&&!before.recalledAt){
  if(!before.employee)throw [409,'Die Mitteilung ist noch nicht auf dem Server gespeichert. Bitte kurz abgleichen und erneut versuchen.'];
  if(String(before.employee)!==String(user.id))throw [403,'Nur der Absender darf diese Mitteilung zurückrufen.'];
  if(before.officeViewedAt)throw [409,'Die Mitteilung wurde vom Büro bereits gelesen und kann nicht mehr zurückgerufen werden.'];
  result.recalledAt=now;result.recalledBy=user.id;result.deletedAt=now;result.updatedAt=now;
 }
 for(const key of ['officeViewedAt','officeViewedBy','officeViewedByName','officeViewedByAccountName','officeViewedByTestIdentity'])if(before[key])result[key]=before[key];
 if(before.officeHandledAt){result.officeHandledAt=before.officeHandledAt;result.officeHandledBy=before.officeHandledBy;result.officeHandledByName=before.officeHandledByName;}
 else if(result.officeHandledAt){if(!['owner','operator','admin'].includes(role))throw [403,'Nur Inhaber, Operator oder Admin dürfen eine Meldung bestätigen.'];result.officeHandledAt=now;result.officeHandledBy=user.id;result.officeHandledByName=user.name||user.id;}
 return result;
}
