async function sendAccountEmail(env,to,subject,text,html='',kind='other'){
 requireAccountEmailReady(env);
 let response;
 if(String(env.BREVO_API_KEY||'').trim())response=await fetch('https://api.brevo.com/v3/smtp/email',{method:'POST',headers:{'api-key':env.BREVO_API_KEY,accept:'application/json','content-type':'application/json'},body:JSON.stringify({sender:accountEmailSender(env),to:[{email:to}],subject,textContent:text,...(html?{htmlContent:html}:{})})});
 else response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{authorization:`Bearer ${env.RESEND_API_KEY}`,'content-type':'application/json'},body:JSON.stringify({from:accountEmailFrom(env),to:[to],subject,text,...(html?{html}:{})})});
 if(!response.ok){await recordPlatformEmailUsage(env,kind,'failed');throw [502,'Die E-Mail konnte nicht versendet werden.'];}
 if(String(env.BREVO_API_KEY||'').trim()){
  const accepted=await response.json().catch(()=>({})),messageId=String(accepted?.messageId||'');
  if(messageId){
   await new Promise(resolve=>setTimeout(resolve,750));
   const events=await accountEmailEvents(env,to),failure=events.find(row=>row.messageId===messageId&&['error','blocked','hardBounces','softBounces','invalid'].includes(row.event));
   if(failure){await recordPlatformEmailUsage(env,kind,'failed');throw [503,failure.reason.includes('sending platform is currently disabled')?'Der E-Mail-Versand ist beim Anbieter derzeit deaktiviert. Bitte das Brevo-Konto reaktivieren.':'Die E-Mail wurde vom Versanddienst abgelehnt.'];}
  }
 }
 await recordPlatformEmailUsage(env,kind,'accepted');
}
async function accountEmailEvents(env,email){
 if(!String(env.BREVO_API_KEY||'').trim())return [];
 const url=new URL('https://api.brevo.com/v3/smtp/statistics/events');
 url.searchParams.set('email',normalizeEmail(email));url.searchParams.set('limit','20');url.searchParams.set('sort','desc');
 const response=await fetch(url,{headers:{'api-key':env.BREVO_API_KEY,accept:'application/json'}});
 if(!response.ok)throw [502,'Der Zustellstatus konnte nicht geprüft werden.'];
 const body=await response.json();
 return (Array.isArray(body?.events)?body.events:[]).map(row=>({event:String(row.event||''),date:String(row.date||''),subject:String(row.subject||''),messageId:String(row.messageId||''),reason:String(row.reason||row.tag||'')}));
}
