function decodedImage(data){
 const match=String(data||'').match(/^data:(image\/(?:jpeg|png|webp|gif));base64,([A-Za-z0-9+/=\r\n]+)$/i);if(!match)throw [415,'Das Originalfoto ist nicht lesbar.'];
 const binary=atob(match[2].replace(/\s/g,'')),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return {type:match[1].toLowerCase(),bytes};
}
async function sendResetEmail(env,to,code,accountId,companyNames=''){ 
 const company=String(companyNames||'').trim();
 try{await sendAccountEmail(env,to,'HausmeisterGo – Zugangsdaten wiederherstellen',`Deine Konto-ID lautet: ${accountId}${company?`\nFirma: ${company}`:''}\n\nDein einmaliger Wiederherstellungscode lautet: ${code}\n\nDer Code ist 15 Minuten gültig. Falls du ihn nicht angefordert hast, kannst du diese Nachricht ignorieren.`,'','reset');}catch(error){if(Array.isArray(error)&&error[0]===502)throw [502,'Die Wiederherstellungs-E-Mail konnte nicht versendet werden.'];throw error;}
}
