async function readBody(request){if(Number(request.headers.get('content-length')||0)>64*1024*1024)throw [413,'Anfrage zu groß.'];try{return await request.json();}catch{throw [400,'Ungültige Anfrage.'];}}
async function auth(request,env){const token=request.headers.get('authorization')?.replace(/^Bearer /,'')||'';if(!token)throw [401,'Anmeldung erforderlich.'];const hash=await sha256(token),now=Math.floor(Date.now()/1000);const row=await env.DB.prepare('SELECT u.id,u.name,u.role,u.active FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>? AND u.active=1').bind(hash,now).first();if(!row)throw [401,'Sitzung abgelaufen.'];return row;}
