  if(env.CUSTOMER_LICENSE_REQUIRED!=='true'||env.CUSTOMER_LICENSE_ORIGIN!==url.origin||!env.CUSTOMER_LICENSE_PUBLIC_KEY||!/^[a-f0-9]{64}$/.test(setupDigest))throw [404,'Geführte Ersteinrichtung ist hier nicht verfügbar.'];
