  let pending;try{pending=buildPendingCheckout(data,packageDefinition,{orderId:crypto.randomUUID(),setupId:crypto.randomUUID(),reservedTenantId:tenantSlug(data?.companyName),createdAt:now,expiresAt:now+30*60000});}catch(error){throw [400,error.message||'Die Bestellung ist ungültig.'];}
  const ip=String(request.headers.get('CF-Connecting-IP')||'unknown'),emailHash=await sha256(`checkout-email:${pending.setup.email}`),companyHash=await sha256(`checkout-company:${pending.setup.companyName.toLocaleLowerCase('de-DE')}`),ipHash=await sha256(`checkout-ip:${ip}`);
  const recent=await env.DB.prepare('SELECT email_hash AS emailHash,company_hash AS companyHash,ip_hash AS ipHash,created_at AS createdAt FROM platform_checkout_request_limits WHERE created_at>?').bind(now-3600000).all(),rate=checkoutRequestAllowed((recent.results||[]).map(row=>({emailMatch:row.emailHash===emailHash,companyMatch:row.companyHash===companyHash,ipMatch:row.ipHash===ipHash,createdAt:Number(row.createdAt)})),now);
